import sys
from collections import defaultdict

def main():
    input = sys.stdin.readline
    first_line = input()
    if not first_line:
        return

    n = int(first_line)

    total = defaultdict(int)
    pending_start = {}
    friends = set()

    current_time = 0
    pending_delay = None
    first_event = True

    for _ in range(n):
        parts = input().split()
        typ = parts[0]
        x = int(parts[1])

        if typ == 'T':
            if pending_delay is None:
                pending_delay = x
            else:
                pending_delay += x
        else:
            if first_event:
                current_time = 0
                first_event = False
            else:
                if pending_delay is None:
                    current_time += 1
                else:
                    current_time += pending_delay

            pending_delay = None
            friends.add(x)

            if typ == 'R':
                pending_start[x] = current_time
            else:
                if x in pending_start:
                    total[x] += current_time - pending_start[x]
                    del pending_start[x]

    out = []
    for friend in sorted(friends):
        if friend in pending_start:
            out.append(f"{friend} -1")
        else:
            out.append(f"{friend} {total[friend]}")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
